  "title": "客栈奇遇",
  "scene": "深夜，你躲在一间客栈的角落，观察着来来往往的武林人士。一名自称‘飞鹰’的神秘人带着一个包裹匆匆离去，引起了你的注意。这时，一个老茶客在你耳边低语，说‘飞鹰’可能在客栈的东厢房有秘密。你注意到包裹上有一个小小的铁环，与东厢房门把手上的一模一样。",
  "goal": "找到‘飞鹰’的秘密包裹",
  "clue": "包裹上的铁环与东厢房门把手上的铁环相同",
  "choices": [
    {"id": "A", "text": "潜入东厢房查看", "outcome": "你发现一个隐蔽的暗格，里面放着一封书信和一些银两。书信提及‘飞鹰’与‘天琊门’的恩怨。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "询问客栈其他住客", "outcome": "你询问了几个人，没有人见过‘飞鹰’，没有获得关于包裹的线索。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "跟随‘飞鹰’离开", "outcome": "你跟随‘飞鹰’到了附近的酒铺，但他没有停留，继续前行。", "result": "fail", "next": "retry"}
  ]
}
